WITH original_packs(title,worked,explanation,task,answer) AS (
 VALUES
('أدوات الاستفهام','في «أين الحقيبة؟» نسأل عن المكان، وفي «متى تبدأ الحصة؟» عن الزمن، و«من حضر؟» عن الشخص.','تختار الأداة وفق المعلومة المطلوبة؛ لا يصح وضع «أين» للسؤال عن الزمن.','كوّن سؤالًا مناسبًا لإجابة «في المكتبة»، وآخر لإجابة «يوم الخميس».','«أين كنتَ؟ — في المكتبة»، و«متى الموعد؟ — يوم الخميس».'),
('أشكال الحرف في الكلمة','لحرف الباء شكل في أول «بَاب»، وشكل في وسط «حَبْل»، وشكل في آخر «كِتَاب».','يتغيّر رسم بعض الحروف بحسب موضعها واتصالها، مع بقاء صوت الحرف نفسه.','حدد مكان الباء في «باب، حبل، كتاب»، ثم اكتب كلمة جديدة فيها باء في وسطها.','في «باب» باء في الأول والأخير، وفي «حبل» بالوسط، وفي «كتاب» بالآخر.'),
('أقسام الكلام','في «قرأَ خالدٌ في الصفِّ» نجد الفعل «قرأ»، والاسمين «خالد، الصف»، والحرف «في».','الفعل يدل على حدث وزمن، والاسم يدل على مسمّى، والحرف يؤدي معنى عند اتصاله بغيره.','صنّف «كتبَ، شجرةٌ، من، طفلٌ» ثم اكتب جملة تجمع الأقسام الثلاثة.','«كتبَ» فعل، و«شجرةٌ، طفلٌ» اسمان، و«من» حرف جر.'),
('إن وأخواتها','«العلمُ نورٌ» تصبح «إنَّ العلمَ نورٌ»؛ دخلت إنَّ فنصبت المبتدأ وصار اسمها وبقي الخبر مرفوعًا.','إنَّ وأخواتها حروف ناسخة تنصب الاسم وترفع الخبر؛ انتبه إلى اختلاف المعنى بين التوكيد والتمني والترجي.','حوّل «الجوُّ جميلٌ» باستخدام «إنَّ»، وبيّن اسمها وخبرها.','«إنَّ الجوَّ جميلٌ»: الجوَّ اسم إن منصوب، وجميلٌ خبرها مرفوع.'),
('الأصوات والحروف','انطق أول «سَمَك» ثم أشِر إلى حرف «س» المكتوب؛ كرر بصوت الميم في «مَاء».','الصوت ما ننطقه ونسمعه، والحرف رمز نقرأه ونكتبه؛ لا نخلط اسم الحرف بصوته داخل الكلمة.','اختر حرف البداية في «بَيْت، وَرْد، قَمَر»، واقرأ كلمتين ببطء.','الباء في «بيت»، والواو في «ورد»، والقاف في «قمر».'),
('الإملاء وعلامات الترقيم','قارن «أين ذهبتَ؟» و«ذهبتُ إلى المدرسة.»؛ الأول سؤال ينتهي بعلامة استفهام، والثاني خبر تنهيه نقطة.','الترقيم يدل على نوع الجملة ويساعد القارئ على فهم الوقف والمعنى، والهمزات جزء من صحة الكتابة.','ضع علامتي ترقيم في «ما اسمك» و«الجو معتدل»، ثم صحح «انا احب القراءه».','«ما اسمك؟» و«الجو معتدل.»، ويمكن كتابة «أنا أحب القراءة».'),
('الإيجاز والإطناب','«نجح الفريق» تعبير موجز، و«نجح الفريق بعد تدريب طويل وتعاون دقيق» توسع يضيف تفاصيل للمعنى.','ليست الزيادة خطأ دائمًا؛ الإطناب المقبول يزيد فائدة، والإيجاز يوصل المعنى دون إخلال.','اختصر «قام الطالب بالذهاب إلى المدرسة في الصباح» إلى صياغة أقصر، ثم وسعها بتفصيل مفيد.','«ذهب الطالب إلى المدرسة صباحًا» اختصار صحيح؛ ويمكن إضافة «مبكرًا استعدادًا للامتحان» لمعلومة مفيدة.'),
('الاستعارة والصورة','في «ابتسم الصباح» نُسب الابتسام إلى الصباح للتصوير، لا لأن للصباح وجهًا يبتسم حقيقة.','الاستعارة توظف لفظًا في غير معناه الحقيقي لعلاقة مشابهة مع قرينة تمنع إرادة الحقيقة؛ حدّد أثر الصورة في المعنى.','فسر الصورة في «همست الأشجارُ للريح»، ثم أعد صياغتها وصفًا مباشرًا.','الصورة توحي بهدوء حركة الأوراق؛ والوصف المباشر «تحركت أوراق الأشجار بصوت خافت».'),
('الاستماع واتباع التعليمات','اسمع التعليمات الأصلية «افتح الدفتر، اكتب التاريخ، ثم ضع خطًا تحت العنوان»، ثم نفذها بالترتيب.','يُقاس الاستماع بفهم المطلوب والترتيب لا بمجرد تكرار الكلمات؛ اطلب إعادة التعليمات عند عدم وضوحها.','اقرأ التعليمات الثلاث مع زميلك أو معلمك، ثم نفذها دون النظر إليها، واذكر أي خطوة سبقت الأخرى.','يفتح الدفتر أولًا، ثم يُكتب التاريخ، وأخيرًا يُوضع خط تحت العنوان.'),
('الاستنتاج من النص','«حملت سلمى المظلة قبل خروجها ورأت الغيوم الكثيفة»؛ نستنتج أنها تتوقع المطر، مع أن النص لم يصرح به.','الاستنتاج فكرة يدعمها دليل من النص؛ لا نضيف أحداثًا لا سند لها.','اقرأ «أطفأ سامر مصباح الغرفة ثم أغلق بابها»؛ ماذا يمكن أن نستنتج؟ وما الدليل؟','قد يكون سامر غادر الغرفة؛ والدليل إطفاء المصباح وإغلاق الباب، وهو احتمال وليس حقيقة صريحة.'),
('الاستنتاج وبناء الحجة','«انخفض الهدر بعد إصلاح الصنبور» دليل يؤيد أن صيانة التسرب تساعد على توفير الماء؛ لكنه لا يثبت وحده أنها السبب الوحيد.','الحجة تربط ادعاءً واضحًا بدليل ملائم وتناقش حدود الدليل والبدائل.','قدّم ادعاءً حول القراءة اليومية، ودليلًا يمكن جمعه دون اختلاق أرقام، واعتراضًا محتملًا.','يمكن القول إن القراءة المنتظمة تحسن الممارسة، والدليل مقارنة تقدم الطالب في نصوص متكافئة مع مراعاة عوامل أخرى.'),
('البحث والتوثيق','اكتب سؤالًا محددًا «كيف نحمي الماء في المدرسة؟» ثم سجل اسم المصدر وعنوان الصفحة وتاريخ الوصول قبل تدوين معلومة منه.','التوثيق يسمح بالرجوع إلى الدليل ويميز المعلومة المنقولة عن رأي الباحث؛ لا تُنشئ مرجعًا غير موجود.','ضع خطة من ثلاث خطوات للبحث عن موضوع لغوي، مع مثال لبيان اسم مؤلف أو جهة وعنوان العمل.','سؤال واضح ← اختيار مصادر موثوقة ← تدوين بيانات المصادر ومقارنة المعلومات؛ تُذكر جهة المصدر وتاريخه إن وُجدا.'),
('التشبيه وأثره','«الطالبُ كالنحلةِ نشاطًا» تشبيه؛ الطالب مشبه، والنحلة مشبه به، والكاف أداة، والنشاط وجه الشبه.','التشبيه يقرب المعنى بمقارنة محددة؛ وجود الكاف لا يكفي دائمًا للحكم من غير فهم السياق.','حلل «العلمُ كالنورِ هدايةً»، ثم كوّن تشبيهًا جديدًا.','المشبه «العلم»، والمشبه به «النور»، والأداة «الكاف»، والوجه «الهداية».'),
('التلخيص الأكاديمي','فقرة تذكر مشكلة الهدر وأسبابه وحلوله تُلخص بقول «يناقش النص هدر المياه وأسبابه وأبرز طرق معالجته».','التلخيص يحافظ على الأطروحة والنقاط المحورية دون نقل الأمثلة الثانوية أو إدخال رأي الملخص.','اكتب ملخصًا من جملتين لقطعة تعليمية من اختيارك، ثم أشر إلى فكرة رئيسة حذفتَ مثالها.','يذكر الملخص السؤال الرئيس وأهم النتائج بدقة؛ لا يصح تحويل فرضية النص إلى حقيقة مؤكدة.'),
('التوابع والاتساق','«حضرَ الطالبُ المجتهدُ والمعلمُ»؛ «المجتهد» نعت يوافق المنعوت، و«المعلم» معطوف يتبع المعطوف عليه في الإعراب.','التابع يرتبط بما قبله بعلاقة نحوية، ويساعد الاتساق على ربط المعاني دون تكرار مرهِق.','حدد النعت والمعطوف في «قرأَ التلميذُ الصغيرُ القصةَ والقصيدةَ».','«الصغيرُ» نعت مرفوع لـ«التلميذُ»، و«القصيدةَ» معطوف منصوب على «القصةَ».'),
('الجملة الاسمية البسيطة','«الحديقةُ جميلةٌ» جملة تبدأ باسم، «الحديقةُ» مبتدأ و«جميلةٌ» خبر يوضح حالها.','نحتاج مبتدأ نخبر عنه وخبرًا يتمم المعنى، ويمكن أن يكون الخبر مفردًا في الأمثلة السهلة.','رتّب «مفيدٌ، الكتابُ» في جملة، ثم حدّد المبتدأ والخبر.','«الكتابُ مفيدٌ»: الكتابُ مبتدأ مرفوع ومفيدٌ خبر مرفوع.'),
('الجملة الفعلية البسيطة','«زرعَ الطفلُ زهرةً» تبدأ بفعل، والطفل قام بالفعل، والزهرة وقع عليها الزرع.','الجملة الفعلية في المثال تبدأ بفعل، ويأتي بعده فاعله، وقد يتبعها مفعول به إذا كان الفعل متعديًا.','رتّب «الفلاحُ، سقى، الزرعَ» ثم حدّد من قام بالعمل.','«سقى الفلاحُ الزرعَ»: الفعل سقى، والفاعل الفلاحُ، والمفعول به الزرعَ.'),
('الحال والتمييز','«عادَ الطالبُ مسرورًا» الحال يبين هيئة الطالب وقت العودة؛ «اشتريتُ لترًا ماءً» تمييز يزيل إبهام المقدار.','الحال غالبًا يجيب عن «كيف؟»، والتمييز يوضح ذاتًا أو نسبة مبهمة؛ لا نخلطهما لمجرد أنهما منصوبان.','حدد الحال في «دخلَ المعلمُ مبتسمًا»، والتمييز في «عندي عشرون كتابًا».','«مبتسمًا» حال، و«كتابًا» تمييز يوضح العدد.'),
('الحال والتمييز المتقدم','«ازدادَ الباحثُ علمًا» تمييز نسبة يوضح جهة الازدياد، و«رجعَ الباحثُ مسرورًا» حال يبين هيئته.','ليس كل منصوب بعد فعل حالًا؛ اختبر إن كان يزيل إبهام معنى النسبة أو يصف الهيئة عند وقوع الحدث.','وازن بين «امتلأَ الإناءُ ماءً» و«عادَ الرياضيُّ متعبًا» مع تعليل الوظيفة.','«ماءً» تمييز نسبة يزيل الإبهام، و«متعبًا» حال يصف هيئة الرياضي.'),
('الحجاج والمناظرة','يقول طالب «نقترح زيادة وقت القراءة لأننا نحتاج فرصة لمناقشة النصوص»، ويرد آخر «كيف نحافظ على حصص أخرى؟».','المناظرة تناقش الرأي بالدليل وباحترام الاعتراض، ولا يُرفض الشخص لمجرد اختلافه.','اكتب ادعاءً ودليلًا واعتراضًا وردًا مناسبًا حول تخصيص وقت للقراءة.','المثال الجيد يوضح الموقف وسببًا يمكن اختباره ويجيب عن الاعتراض دون سخرية.'),
('الحجة وتقويم الأدلة','الادعاء «كل الطلاب يفضلون القراءة» لا يثبت باستطلاع ثلاثة طلاب فقط؛ الدليل محدود والعينة لا تمثل الجميع.','قيّم مصدر الدليل وحجمه وصلته بالادعاء، وفرّق بين الملاحظة والتعميم.','اختر دليلًا أقوى بين رأي فرد واحد ونتائج استبانة موضحة العينة وطريقة جمعها، مع بيان القيود.','الاستبانة الموثقة أقدر على دعم اتجاه عام من رأي واحد، لكن حجم العينة وتحيازها مهمان.'),
('الحركات القصيرة','نقرأ «كَتَبَ» بالفتحة، و«كُتُبٌ» بالضمة في مقاطعها، و«كِتَابٌ» بكسرة الكاف.','الفتحة والضمة والكسرة حركات قصيرة تغير الصوت، وقد يختلف المعنى بتغير الضبط.','انطق «بَ، بِ، بُ»، ثم كوّن مقطعين بحرف الميم واضبطهما.','«مَ، مِ، مُ» أصوات قصيرة مختلفة، وموضع الحركة فوق الحرف أو تحته مهم.'),
('الحوار المنظم','يبدأ أحمد «ما رأيك في الحفاظ على الحديقة؟»، وتجيب ليلى، ثم يعيد أحمد صياغة فكرتها قبل التعقيب.','تنظيم الحوار يحتاج سؤالًا واضحًا وإنصاتًا وتبادل أدوار ولغة محترمة؛ لا تقاطع المتحدث.','اكتب حوارًا من أربعة أسطر بين طالبين يناقشان قراءة قصة، مع سؤال ورد وتلخيص.','يقبل الحوار إذا ظهرت فيه أدوار متبادلة، وسؤال مناسب، ورد مرتبط، وتلخيص للرأي.'),
('الدلالة والسياق','في «جذرُ الشجرة قوي» الجذر جزء من النبات، وفي «جذرُ المشكلة عميق» يدل على أصلها مجازًا.','معنى الكلمة يتغير بسياقها؛ لا نعتمد أول معنى في القاموس من غير قراءة الجملة.','فسّر «عين» في «عينُ الماء صافية» و«عينُ الطفل سليمة».','الأولى منبع الماء، والثانية عضو البصر؛ السياق يمنع الخلط.'),
('الرسالة القصيرة','«إلى صديقي يوسف، أشكرك على مساعدتي في مشروع القراءة. مع التحية، سامي».','تتضمن الرسالة جهة المخاطب وغرضًا واضحًا وخاتمة وتوقيعًا يناسب الموقف.','اكتب رسالة شكر إلى معلم أو قريب في ثلاثة أسطر دون مبالغة.','تكون واضحة إذا تضمنت المخاطب، سبب الشكر المحدد، والخاتمة المهذبة.'),
('السبب والنتيجة','«هطل المطر فابتلت الأرض»: هطول المطر سبب وابتلال الأرض نتيجة في المثال.','ابحث عن علاقة صريحة أو معقولة بين حدثين؛ وقوع حدثين متتاليين لا يعني دائمًا أن الأول سبب الثاني.','حدد السبب والنتيجة في «تدرّبت مريم بانتظام، فتحسنت قراءتها»، ثم اكتب مثالًا جديدًا.','السبب المصرح به التدريب المنتظم والنتيجة تحسن القراءة؛ احذر التعميم على كل حالة دون دليل.'),
('السكون والمقطع','في «مَدْ» الميم مفتوحة والدال ساكنة؛ ننطق المقطع مع الوقف على الدال دون حركة قصيرة بعدها.','السكون علامة على غياب حركة قصيرة بعد الحرف، فينتقل الصوت إليه من الحرف المتحرك قبله.','اقرأ «مِنْ، لَمْ، بَلْ» وانطق الحرف الساكن في نهاية كل مثال.','النون في «مِنْ» والميم في «لَمْ» واللام في «بَلْ» عليها سكون.'),
('السياق الثقافي للنص','قد يذكر نص سوقًا قديمًا أو مثلًا شعبيًا؛ نفهمه أولًا من عصره وبيئته قبل مقارنته بحاضرنا.','السياق الثقافي يفسر العادات والدلالات لكنه لا يبرر اختراع معلومات عن المؤلف أو العصر.','حدد كلمة أو عادة في نص تختاره تحتاج إلى تفسير ثقافي؛ ما المصدر الذي ستعود إليه؟','الإجابة المقبولة تسمي موضعًا من النص، وسؤالًا تاريخيًا محددًا، ومصدرًا موثوقًا للفحص.'),
('الشدة والتنوين','في «مُعَلِّم» الحرف المشدد يُنطق كحرفين أولهما ساكن والثاني متحرك؛ وفي «كِتابٌ» تنوين ضم.','الشدة تقوي الحرف بنطق مزدوج، والتنوين نون ساكنة تُنطق ولا تُكتب نونًا منفصلة آخر الاسم.','انطق «شَدَّ» وحدد المشدد، ثم اقرأ «قلمٌ، قلمًا، قلمٍ».','الدال مشددة في «شدّ»، وتنوين الضم والفتح والكسر أصوات مختلفة في الأمثلة.'),
('الشرط والاستثناء','«إنْ تجتهدْ تنجحْ» أسلوب شرط جازم، و«حضرَ الطلابُ إلا طالبًا» استثناء من جماعة مذكورة.','الشرط يربط حصول أمر بأمر آخر، أما الاستثناء فيخرج عنصرًا من حكم سابق؛ لكل منهما أدوات وأحكام.','حلل أداة الشرط في «إنْ تقرأْ تتعلمْ» وأداة الاستثناء في «حضرتُ الدروسَ إلا درسًا».','«إنْ» أداة شرط جازمة، و«إلا» أداة استثناء؛ «درسًا» مستثنى منصوب في المثال التام المثبت.'),
('الصورة الفنية','«المدينةُ تلبس ثوبَ الضوء» تعبير يصور الإضاءة كأنها ثوب؛ ليس وصفًا حرفيًا لملابس المدينة.','تجعل الصورة الفنية المعنى محسوسًا وتثير التخيل، لكن الحكم على أثرها يحتاج إلى سياق النص.','صف أثر صورة «تضحكُ الأزهارُ» ثم اكتب عبارة خبرية تؤدي معناها دون تصوير.','الصورة توحي بالجمال والحيوية؛ ويمكن التعبير عنها بقول «تبدو الأزهار جميلة ومتفتحة».'),
('العرض الشفهي','ابدأ «سأتحدث عن ترشيد الماء»، ثم اعرض سببين ونصيحتين، واختم بخلاصة قصيرة.','الجمهور يحتاج ترتيبًا وصوتًا واضحًا وأمثلة مناسبة للوقت؛ لا تُقرأ الشرائح كلمة بكلمة.','حضّر عرضًا من دقيقة عن كتاب أحببته يتضمن مقدمة وفكرة ودليلًا وخاتمة.','ينجح العرض إذا كانت رسالته واضحة ومتسلسلة والصوت مناسبًا والوقت محترمًا.'),
('العرض والمناقشة','يقول متحدث «أعرض أثر القراءة المنتظمة»، ثم يدعو للسؤال ويجيب «بحسب المثال الذي راجعناه...».','المناقشة تتميز عن الإلقاء بإدارة الأسئلة والاعتراف بحدود المعرفة وتوثيق ما يحتاج مراجعة.','اصنع مخطط عرض بثلاث أفكار، وجهز سؤالين متوقعين وإجابةً مستندة إلى مصدر.','العمل الجيد يبين الأفكار وأدلتها ويحدد ما هو رأي وما يحتاج تحققًا.'),
('الفعل والفاعل','«رسمَ الطفلُ لوحةً»: رسم فعل ماض والطفل فاعل مرفوع لأنه قام بالرسم.','اسأل «من فعل؟» لتحديد الفاعل، ولا تجعل المفعول به فاعلًا لمجرد أنه يأتي بعد الفعل.','حدد الفعل والفاعل في «تعاونَ الطالبانِ في المشروع» ثم ألف جملة جديدة.','«تعاونَ» فعل ماض، و«الطالبانِ» فاعل مرفوع بالألف لأنه مثنى.'),
('الفكرة الرئيسة','«زرعت ليلى شتلة وسقتها وحافظت عليها»: الفكرة الرئيسة العناية بالنباتات، أما الري فهي تفصيل.','الفكرة العامة تشمل معنى النص كله، بينما التفصيل يوضحها بمثال أو حدث.','اكتب عنوانًا مناسبًا للجمل الثلاث، واذكر تفصيلًا واحدًا يؤيده.','«العناية بالنبات» عنوان مناسب، و«سقت الشتلة» تفصيل يوضحه.'),
('الفكرة الرئيسة والتفاصيل','في فقرة عن النظافة، «الحفاظ على نظافة المدرسة مسؤولية مشتركة» فكرة رئيسة، و«جمع الأوراق في السلة» تفصيل.','التفاصيل أمثلة وأدلة توضّح الفكرة ولا تحل محلها.','اقترح فكرة رئيسة لفقرة عن القراءة اليومية، ثم اكتب تفصيلين يمكن أن يدعماها.','«القراءة عادة نافعة» فكرة، وتفصيلان مثل اكتساب مفردات جديدة والتعرف إلى موضوعات متنوعة.'),
('القراءة الجهرية المعبرة','اقرأ «ما أجملَ الحديقة!» بنبرة تعجب، و«أينَ الكتاب؟» بنبرة استفهام مع وقفة مناسبة.','النطق السليم والوقف والتنغيم تخدم المعنى، لكن سرعة القراءة وحدها لا تدل على الفهم.','اقرأ جملة خبرية وأخرى استفهامية، وسجل موضع الوقف ونبرة الصوت مع زميلك.','تنتهي الجملة الخبرية بوقف هادئ، ويراعى الاستفهام عند علامة السؤال.'),
('القراءة النقدية','إذا قال النص «هذا الحل يصلح للجميع» نسأل: من المقصود بالجميع؟ وما الأدلة؟ وما البدائل؟','القارئ الناقد يميز الادعاء عن الدليل ويبحث عن افتراضات أو تعميمات غير مدعومة.','اختر رأيًا في فقرة تعليمية وصغ سؤالين لاختبار قوة الدليل، دون مهاجمة الكاتب.','مثال: «ما مصدر هذه النتيجة؟» و«هل يشمل الدليل فئات مختلفة؟».'),
('الكتابة الوظيفية','رسالة طلب استعارة كتاب تذكر المخاطب والطلب وسببًا موجزًا والموعد المقترح، دون مقدمة إنشائية طويلة.','الغرض يحدد شكل الكتابة؛ الرسالة الرسمية تختلف عن التأمل الأدبي في اللغة والترتيب.','اكتب بريدًا رسميًا قصيرًا تطلب فيه حجز قاعة للمطالعة مع موعد وسبب واضحين.','ينبغي أن يتضمن موضوعًا مباشرًا وطلبًا مهذبًا وتفاصيل تسمح بالرد.'),
('اللام الشمسية والقمرية','في «الشَّمس» لا نلفظ لام «الـ» وتُشدَّد الشين، وفي «الْقمر» نلفظ اللام بوضوح.','الحكم يعتمد على الحرف الذي يلي «الـ» التعريف؛ لا ننظر إلى نوع الكلمة أو معناها.','صنّف «الطَّالب، الْباب، النَّهر، الْكتاب» إلى شمسية وقمرية.','«الطالب، النهر» شمسيتان؛ «الباب، الكتاب» قمريتان.'),
('المبتدأ والخبر','«العلمُ مفيدٌ»: العلمُ مبتدأ مرفوع، ومفيدٌ خبر مرفوع يتمم المعنى.','تحديد الخبر يكون بالسؤال عما أخبرنا به عن المبتدأ لا بمجرد ترتيب كلمتين.','حدد المبتدأ والخبر في «الطريقُ طويلٌ»، ثم اكتب جملة اسمية من إنشائك.','«الطريقُ» مبتدأ و«طويلٌ» خبر، وكلاهما مرفوع في المثال.'),
('المبني للمعلوم والمجهول','«كتبَ الكاتبُ الرسالةَ» مبني للمعلوم، و«كُتبتِ الرسالةُ» مبني للمجهول، فحذف الفاعل وصارت الرسالة نائب فاعل.','يتغير بناء الفعل، ويرتفع نائب الفاعل؛ لا نصفه بالفاعل نفسه في هذا التركيب.','حوّل «فتحَ العاملُ البابَ» إلى المبني للمجهول مع ضبط الصياغة.','«فُتحَ البابُ»: البابُ نائب فاعل مرفوع.'),
('المفاعيل ودلالاتها','«قرأتُ الكتابَ صباحًا»: الكتابَ مفعول به، وصباحًا ظرف زمان في هذا السياق.','وظيفة المنصوب تتحدد بعلاقته بالحدث لا بنهايته فقط؛ قارن المفعول به والمفعول فيه والمطلق.','بيّن نوع «الدرسَ» في «راجعتُ الدرسَ»، و«مساءً» في «درستُ مساءً».','«الدرسَ» مفعول به، و«مساءً» مفعول فيه ظرف زمان.'),
('المفرد والجمع','«قلم» مفرد و«أقلام» جمع، و«طالب» مفرد و«طلاب» جمع.','المفرد يدل على واحد، والجمع يدل على أكثر من اثنين؛ تتغير صورة الجمع بحسب الكلمة.','ضع جمع «كتاب، شجرة» في جملة، واذكر مفرد «دفاتر».','«كتب، شجرات، دفتر» إجابات مناسبة.'),
('المفعول به','«قرأَ الطفلُ القصةَ»: الطفلُ فاعل والقصةَ مفعول به وقع عليه الفعل.','نسأل «ماذا قرأ الطفل؟» فنجد «القصةَ»؛ وهي منصوبة في المثال.','استخرج المفعول به من «فتحَ الحارسُ البابَ»، ثم ضع «زهرةً» في جملة صحيحة.','«البابَ» مفعول به، ومثال آخر «زرعتُ زهرةً».'),
('المقارنة بين نصين','نص عن المحافظة على الماء يورد إرشادات، ونص آخر يحكي قصة عن هدر الماء؛ الموضوع واحد لكن الأسلوب والغرض مختلفان.','المقارنة تبحث عن أوجه اتفاق واختلاف محددة في الأفكار والأدلة والأسلوب.','أنشئ جدولًا ذا عمودين لنصين قرأتهما، وحدد الفكرة ونوع الدليل والغرض في كل واحد.','الإجابة الجيدة تستشهد بتفصيل من كل نص قبل الحكم، وتفصل التشابه عن الاختلاف.'),
('المقال الحجاجي','ابدأ مقالك بأطروحة «ينبغي دعم المطالعة المدرسية»، ثم سبب ودليل قابل للفحص واعتراض وجواب وخاتمة.','المقال الحجاجي ليس سلسلة آراء دون أدلة، ولا يصح اختلاق إحصاءات لدعم الحجة.','اكتب فقرة حجاجية عن تنظيم وقت المذاكرة، تتضمن اعتراضًا واحدًا والرد عليه.','الفقرة الكاملة تذكر رأيًا واضحًا وسببًا ودليلًا معقولًا واعتراضًا وردًا محترمًا.'),
('النعت والعطف','«قرأتُ قصةً مفيدةً وكتابًا»: «مفيدةً» نعت يتبع «قصةً»، و«كتابًا» معطوف عليها.','النعت يصف الاسم ويوافقه، والعطف يربط بين لفظين أو جملتين بحرف مناسب.','حدد النعت والمعطوف في «زارَ الطفلُ المتحفَ الجميلَ والمكتبةَ».','«الجميلَ» نعت لـ«المتحفَ»، و«المكتبةَ» معطوف منصوب.'),
('النواسخ في السياق','«العلمُ نافعٌ»، وبعد «كان» نقول «كان العلمُ نافعًا»، وبعد «إنَّ» نقول «إنَّ العلمَ نافعٌ».','«كان» ترفع الاسم وتنصب الخبر، و«إنَّ» تنصب الاسم وترفع الخبر، والمعنى يختلف باختلاف الناسخ.','حوّل «السماءُ صافيةٌ» مرة باستخدام «كان» ومرة باستخدام «إنَّ».','«كانت السماءُ صافيةً»، و«إنَّ السماءَ صافيةٌ».'),
('الهمزة والتاء في الكتابة','في «مدرسة» تاء مربوطة (ة)، وفي «بنت» تاء مفتوحة (ت)، وفي «أَكَلَ» همزة قطع.','لا نستبدل الهاء بالتاء المربوطة في كل موضع؛ نحدد بنية الكلمة ونطقها عند الوصل.','صحح «ذهبت الي المدرسه»، ثم قارن كتابة «معلمة» و«أخت».','«ذهبتُ إلى المدرسةِ»، و«معلمة» تاء مربوطة، و«أخت» تاء مفتوحة.'),
('الوصف الدقيق','بدل «حديقة جميلة» قل «حديقة صغيرة تحيط بها أشجار خضراء، وتصل إليها أشعة الصباح».','الوصف الدقيق يستخدم صفات محسوسة وتفاصيل منتقاة، دون مبالغة أو نسخ جمل محفوظة.','صف كرسي الفصل بثلاث جمل تستخدم اللون والحجم والموقع، وتجنب الأحكام العامة.','يكون الوصف جيدًا إذا عرف القارئ الصفات والمكان من الألفاظ المستخدمة.'),
('بناء الفقرة','فقرة عن الرياضة: جملة موضوع «الرياضة عادة صحية»، ثم تفصيلان يشرحان فائدتها، وأخيرًا خلاصة.','كل فقرة تعالج فكرة محورية؛ الروابط المنطقية أفضل من جمع جمل لا علاقة بينها.','رتب «القراءة توسع المعرفة / نتعلم بها كلمات / لذلك نخصص لها وقتًا» في فقرة متماسكة.','«القراءة توسع المعرفة، ونتعلم بها كلمات جديدة؛ لذلك نخصص لها وقتًا كل يوم».'),
('بناء الكلمة من المقاطع','«كَ + تَ + بَ» ننطق المقاطع القصيرة متتابعة لنقرأ «كَتَبَ».','قسّم الكلمة إلى مقاطع صوتية مناسبة، ثم اجمع الأصوات تدريجيًا؛ لا تُهمل الحركات القصيرة.','اقرأ «لَ + عِ + بَ»، ثم اكتب الكلمة دون فواصل.','«لَعِبَ» بعد جمع المقاطع وفق الحركات.'),
('بنية النص وترابطه','«بدأ المشروع بفكرة، ثم جُمعت الأدوات، وبعد ذلك عُرضت النتائج»؛ أدوات الربط توضح التسلسل.','يتضمن النص المتماسك مقدمة أو بداية ذات غرض، وأفكارًا مترابطة، وخاتمة مناسبة.','رتب ثلاث جمل أحداث باستعمال «أولًا، ثم، أخيرًا»، ثم علل ترتيبها.','يقبل الترتيب عندما ترتبط الأحداث زمنيًا وتساعد أدوات الربط القارئ على المتابعة.'),
('تحليل الشعر','اقرأ بيتًا شعريًا متاحًا قانونيًا، وحدد المتكلم والصورة والإيقاع والمعنى قبل إصدار حكم جمالي.','التحليل يفرّق بين الدلالة المباشرة والصورة الفنية والإيقاع والسياق؛ لا تنسب بيتًا إلى شاعر دون مصدر.','اختر بيتًا من مادة درسك وحدد كلمة محورية وصورة ووجهة نظر محتملة للمتكلم.','الإجابة تستشهد بعبارة فعلية من البيت وتوضح علاقة الصورة بفكرته.'),
('تحليل النثر','فقرة تفسيرية تطرح فكرة، وتدعمها بحجج وأمثلة، بخلاف فقرة سردية تعتمد الأحداث والشخصيات.','حلل بنية النص وغرضه ووسائل الربط والألفاظ، ولا تخلط راوي النص بمؤلفه تلقائيًا.','اختر قطعة نثرية وحدد غرضها وفكرتين وأداة ربط ثم دافع عن تحليلك بدليل.','التحليل يحدد نوع البنية ويستند إلى النص لا إلى الانطباع وحده.'),
('تحليل نص أدبي','في نص قصصي قصير اسأل: من الشخصية؟ ما عقدة الحدث؟ كيف تغيّر موقفها؟ وما الدليل؟','التحليل الأدبي يربط العناصر الفنية والدلالات ولا يكفي فيه تلخيص الأحداث.','اكتب تحليلًا لفقرة قصصية قرأتها يتناول حدثًا وشخصيةً وأسلوبًا واحدًا مع شاهد.','يقبل التحليل إذا ميّز بين الحدث والاستنتاج وحلل الوسيلة الأدبية بدليل.'),
('ترتيب الأحداث','«استيقظت مريم، ثم أعدّت حقيبتها، ثم ذهبت إلى المدرسة» ترتيب زمني واضح.','نستخدم كلمات مثل «أولًا، ثم، أخيرًا» لإعادة سرد الأحداث دون تبديل السبب والنتيجة.','رتب «رجع من المدرسة / خرج إلى المدرسة / جهّز حقيبته»، ثم أضف علامة تسلسل.','«جهّز حقيبته، ثم خرج إلى المدرسة، وأخيرًا رجع من المدرسة».'),
('تلخيص فقرة','في نص من ثلاث جمل عن العناية بالشجر، احذف الأمثلة الثانوية واحتفظ بالفكرة التي تجمعها.','التلخيص أقصر من النص الأصلي ويحافظ على الأفكار الأساسية دون إضافة تفاصيل جديدة أو نسخ كل جملة.','لخص فقرة قصيرة من درس آخر في جملة واحدة، ثم بين أي التفاصيل استبعدت.','الإجابة الجيدة تذكر المعنى الرئيس بدقة وتحذف التكرار والأمثلة الهامشية.'),
('حروف الجر','في «الكتابُ على الطاولةِ» حرف الجر «على»، والاسم بعده «الطاولةِ» مجرور.','حرف الجر يربط الاسم بما قبله ويؤثر في إعرابه؛ اختبر معنى المكان أو الابتداء أو الاتجاه.','أكمل «سافرتُ __ المدينةِ» بحرف مناسب، وحدد الاسم المجرور في «جلستُ في الصفِّ».','«سافرتُ إلى المدينةِ»، و«الصفِّ» اسم مجرور بفي.'),
('حروف المد','«باب» فيها ألف مد بعد باء مفتوحة، و«نور» واو مد بعد نون مضمومة، و«فيل» ياء مد بعد فاء مكسورة.','حروف المد الثلاثة: الألف بعد الفتحة، والواو بعد الضمة، والياء بعد الكسرة.','حدد حرف المد في «قال، يقول، كبير»، ثم اقرأها ببطء.','الألف في «قال»، والواو في «يقول»، والياء في «كبير».'),
('قراءة نص قصير','في «زارَت هناءُ الحديقةَ صباحًا، ورأت طائرًا فوق الشجرة» نحدد الشخصية والمكان والزمن.','أقرأ الجمل ثم أجيب من النص أولًا قبل أن أتخيل تفاصيل غير مذكورة.','من زار الحديقة؟ ومتى؟ وأين كان الطائر؟','هناء زارت الحديقة صباحًا، وكان الطائر فوق الشجرة.'),
('قراءة نص معلوماتي','«يوفر النبات الظل، وقد تحتاج بعض النباتات إلى ماء وضوء مناسبين» نص يقدم معلومات لا أحداث قصة.','القارئ يحدد الموضوع والأفكار والروابط ويختبر صحة المعلومة بمصدر موثوق عند الحاجة.','اختر فقرة معلوماتية من درسك وحدد حقيقة واضحة وأخرى تحتاج تحققًا خارجيًا.','الفصل الصحيح بين معلومة مكتوبة ومعلومة تستلزم مصدرًا هو معيار الإجابة.'),
('كان وأخواتها','«الجوُّ معتدلٌ» تصبح «كان الجوُّ معتدلًا»؛ الجو اسم كان مرفوع، ومعتدلًا خبرها منصوب.','كان وأخواتها تدخل على الجملة الاسمية فترفع المبتدأ اسمًا لها وتنصب الخبر.','حول «الحديقةُ واسعةٌ» باستخدام «أصبح»، ثم عيّن الاسم والخبر.','«أصبحتِ الحديقةُ واسعةً»: الحديقةُ اسم أصبح مرفوع، وواسعةً خبرها منصوب.'),
('كتابة تقرير','تقرير عن نشاط مدرسي يتضمن عنوانًا وهدفًا ووقتًا ومكانًا وخطوات ونتائج محددة.','التقرير يصف ما وقع بالفعل دون إضافة أرقام أو أحداث لم تُلاحظ، ويعرض النتائج بوضوح.','اكتب تقريرًا عن نشاط قرائي في المدرسة من خمسة أسطر مع نتيجة واحدة قابلة للتحقق.','يكون التقرير مقبولًا إذا حدد النشاط والهدف والخطوات والنتيجة، وفصل الملاحظة عن الرأي.'),
('كتابة جملة واضحة','«قرأَ الطفلُ كتابًا» جملة واضحة المعنى، بخلاف «الطفلُ في» التي لا يتم فيها المعنى.','اكتب فكرة واحدة بجملة متماسكة وحدد بدايتها ونهايتها بعلامة ترقيم.','رتب «الزهرةَ / سقت / ليلى» ثم اكتب جملة ثانية عن المدرسة.','«سقتْ ليلى الزهرةَ.» مثال صحيح واضح؛ الجملة الثانية ينبغي أن تكون تامة المعنى.'),
('كتابة مقال قصير','ابدأ «القراءة نافعة»، ثم فقرة تعرض فائدتين وخاتمة تلخص الفكرة دون تكرار حرفي.','المقال يحتاج فكرة مركزية وتنظيمًا متدرجًا وروابط بين الجمل، ولو كان قصيرًا.','اكتب مخطط مقال من مقدمة وفقرتين قصيرتين وخاتمة عن نظافة البيئة.','يشمل المخطط موقفًا واضحًا وسببين مدعومين بأمثلة وخلاصة مناسبة.'),
('مراجعة الثانوية الشاملة','راجع موضوعًا نحويًا ونصًا أدبيًا ومهارة كتابة: حدد مهارة الضعف ودليل تقدمك في كل جانب.','المراجعة الفعالة تشخّص موضع الخطأ ثم تعيد التطبيق في مثال مختلف؛ ليست حفظ إجابات السؤال السابق.','اختر مهارتين من وحدتك الحالية واكتب مثالًا صحيحًا لكل واحدة وكيف ستتحقق منه.','الإجابة المقبولة تذكر المعيار والخطأ المحتمل وطريقة تصحيحه مع أمثلة حقيقية من الدرس.'),
('مراجعة القراءة واللغة','اقرأ فقرة قصيرة، استخرج فكرتها، ثم حدد اسمًا وفعلًا وحرفًا من جملة فيها.','تُراجع المهارات في سياق واحد، ثم تفصل الأسئلة لمعرفة ما يحتاج تدريبًا إضافيًا.','اكتب فقرة من ثلاثة أسطر وحدد الفكرة واسمين وفعلًا واحدًا منها.','يصحح الطالب التصنيف بالعودة إلى معنى الكلمات ووظيفتها، ثم يراجع دقة الفكرة.'),
('مراجعة تحليلية شاملة','اختر فقرة من نص درسته، وقدم الفكرة ودليلًا وتحليل أسلوب، ثم أعد كتابة خلاصة دقيقة.','تجمع المراجعة بين فهم النص وبناء الحجة واللغة والتحرير؛ لا يكفي مجرد استرجاع التعريف.','اكتب ثلاث بطاقات: فكرة بدليل، قاعدة بمثال، وفقرة قصيرة تصححها بعد المراجعة.','لكل بطاقة هدف يمكن التحقق منه: شاهد ملائم وتطبيق صحيح وتصحيح مفسر.'),
('مراجعة مهاراتي الأساسية','اقرأ «زرعَ سامرٌ وردةً في الحديقة» ثم حدد الشخص والفعل والمكان بصورة مبسطة.','ابدأ بتعرف أصوات وكلمات، ثم المعنى العام، ثم جملة جديدة من إنشائك تناسب مرحلتك.','اكتب كلمة من النص تبدأ بزاي، وجملة من كلمتين إلى أربع كلمات عن النبات.','«زرعَ» تبدأ بزاي، ومثال جملة «الوردةُ جميلةٌ».'),
('معنى الكلمة من السياق','في «أضاءَت المصابيحُ الغرفةَ» نفهم «أضاءت» من ظهور النور، لا من شكل الكلمة وحده.','القرائن اللفظية والموقف تساعد في تفسير المعنى؛ قد يكون للكلمة أكثر من معنى.','استنتج معنى «غزير» في «هطل مطر غزير فامتلأت البرك»، ثم اكتب جملة جديدة.','«غزير» أي كثير وشديد في السياق، ومثال «تساقط مطر غزير».')
), eligible AS (
 SELECT l.id,l.content, g.grade_number,p.title,p.worked,p.explanation,p.task,p.answer
 FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id
 JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id
 JOIN public.countries co ON co.id=cu.country_id
 JOIN original_packs p ON p.title=l.title
 WHERE l.status='published'
   AND co.is_active AND cu.is_active AND g.is_active
   AND l.content LIKE 'درس ضاديوم الأصلي:%'
   AND length(l.content)<650
   AND l.source_pdf_url IS NULL
   AND l.official_content_scope IS NULL
   AND l.content NOT LIKE '%حزمة ضاديوم الموضوعية المتخصصة%'
), detailed AS (
 SELECT e.*,
   CASE
     WHEN e.grade_number BETWEEN 1 AND 3 THEN
       'خطوة الدعم: اقرأ المثال بصوت واضح مع معلمك، واستعمل بطاقات الكلمات، ثم أجب بكلمة أو جملة قصيرة من إنشائك.'
     WHEN e.grade_number BETWEEN 4 AND 6 THEN
       'خطوة التطبيق: حل التدريب دون نسخ المثال، ثم فسر إجابتك بجملة تستند إلى الفكرة أو القاعدة.'
     WHEN e.grade_number BETWEEN 7 AND 9 THEN
       'خطوة التحليل: بيّن أثر الكلمة أو الأسلوب في المعنى، واختبر إجابتك بمثال مضاد أو شاهد من المادة.'
     ELSE
       'خطوة التعمق: قارن بين استعمالين أو تفسيرين محتملين، وادعم حكمك بدليل نحوي أو نصي واذكر حدوده.'
   END AS differentiation
 FROM eligible e
)
UPDATE public.lessons l
SET content=
  'حزمة ضاديوم الموضوعية المتخصصة — شرح أصلي غير منقول عن الكتاب الوزاري'
  || E'\nالمهارة: ' || d.title
  || E'\n\nأتعلم من مثال محلول:\n' || d.worked
  || E'\n\nأفهم القاعدة أو الفكرة:\n' || d.explanation
  || E'\n\nأطبق بنفسي:\n' || d.task
  || E'\n\nمفتاح المراجعة الذاتية:\n' || d.answer
  || E'\n\n' || d.differentiation
  || E'\n\nمهمة الإتقان: أنشئ مثالًا جديدًا مرتبطًا بالموضوع، وصوّبه وفق القاعدة أو الدليل، ثم وضح لزميلك سبب صحة إجابتك.'
  || E'\n\nتنبيه المصدر: هذا إثراء مستقل لمهارة عربية أساسية لا يثبت تطابق درس رسمي في دولة محددة.'
  || E'\n\nــــــــــــ\nالمادة الأصلية السابقة كما نُشرت:\n\n' || d.content,
  updated_at=now()
FROM detailed d WHERE l.id=d.id
RETURNING l.id,l.title;